properties.expression:
w = thisComp.layer("CONTROLLER").effect("WIDTH")("Slider"); 
h = thisComp.layer("CONTROLLER").effect("HEIGHT")("Slider");
f = framesToTime(1);
dur = outPoint - inPoint;
mid = inPoint + (dur * 0.5);

if(time < mid){
	ease(time, inPoint , mid - f, [w-w,h], [w,h])
}else{
	ease(time, mid , outPoint - f, [w,h], [w-w,h])	
}

s = content("Rectangle 1").content("Rectangle Path 1").size;
dur = outPoint - inPoint;
mid = inPoint + (dur * 0.5);

value + ((time < mid) ? - [s[0] * 0.5, 0] : [s[0] * 0.5, 0]);

s = thisComp.layer("CONTROLLER").effect("WIDTH")("Slider");
dur = outPoint - inPoint;
mid = inPoint + (dur * 0.5);

value + ((time < mid) ? [0,0] : [s, 0]);

transform.expression:
//delayChild

var control = parent.effect("Delay Child");

var randBlend = control(2).value;

var parentDelay = framesToTime(control(1).value);

seedRandom(index+control(3),true);

var delay = linear(randBlend, 0, 100, (index-parent.index)*(parentDelay), (random(-10.5, 21))*(parentDelay));



linear(effect("Delay Child Options")(1).value, 0, 100, value, parent.fromWorld(toWorld(anchorPoint,time-delay)));

//delayChild

var control = parent.effect("Delay Child");

var randBlend = control(2).value;

var parentDelay = framesToTime(control(1).value);

seedRandom(index+control(3),true);

var delay = linear(randBlend, 0, 100, (index-parent.index)*(parentDelay), (random(-10.5, 21))*(parentDelay));



var sX = control(4).valueAtTime(time-delay);

var sY = control(5).valueAtTime(time-delay);

var linX = (sX/100)*(value[0]);

var linY = (sY/100)*(value[1]);

linear(effect("Delay Child Options")(2).value, 0, 100, value, [linX, linY])

//delayChild

var control = parent.effect("Delay Child");

var randBlend = control(2).value;

var parentDelay = framesToTime(control(1).value);

seedRandom(index+control(3),true);

var delay = linear(randBlend, 0, 100, (index-parent.index)*(parentDelay), (random(-10.5, 21))*(parentDelay));



var followParentRotation = value + control(7).valueAtTime(time-delay) - parent.rotationZ + parent.rotationZ.valueAtTime(time-delay);

var maintainRotation = value + control(7).valueAtTime(time-delay) - parent.rotationZ;



linear(effect("Delay Child Options")(3).value, 0, 100, maintainRotation, followParentRotation);

//delayChild

var control = parent.effect("Delay Child");

var randBlend = control(2).value;

var parentDelay = framesToTime(control(1).value);

seedRandom(index+control(3),true);

var delay = linear(randBlend, 0, 100, (index-parent.index)*(parentDelay), (random(-10.5, 21))*(parentDelay));



(parent.enabled) ? linear(effect("Delay Child Options")(4).value, 0, 100, value, control(12).valueAtTime(time-delay)) : 0;

