transform.expression:
var ctrl=thisComp.layer("3D Shape Ctrl");
var rx=degreesToRadians(ctrl.effect("Rotation X")("Angle"));
var ry=degreesToRadians(ctrl.effect("Rotation Y")("Angle"));
var rz=degreesToRadians(ctrl.effect("Rotation Z")("Angle"));
try{if(ctrl.effect("Auto Rotate")("Checkbox")==1)
ry+=degreesToRadians(time*ctrl.effect("Rot Speed")("Slider"));}catch(e){}
var c1=Math.cos(rx),s1=Math.sin(rx);
var c2=Math.cos(ry),s2=Math.sin(ry);
var c3=Math.cos(rz),s3=Math.sin(rz);
function N(n){
var y1=n[1]*c1-n[2]*s1,z1=n[1]*s1+n[2]*c1,x1=n[0];
var x2=x1*c2+z1*s2,z2=-x1*s2+z1*c2,y2=y1;
var x3=x2*c3-y2*s3,y3=x2*s3+y2*c3;
return[x3,y3,z2];}
var rn=N([-1,0,0]);
rn[2]>0?100:0;

properties.expression:
var ctrl=thisComp.layer("3D Shape Ctrl");
var sc=ctrl.effect("Scale")("Slider")/100;
var W=ctrl.effect("Width")("Slider")/2*sc;
var H=ctrl.effect("Height")("Slider")/2*sc;
var D=ctrl.effect("Depth")("Slider")/2*sc;
var rx=degreesToRadians(ctrl.effect("Rotation X")("Angle"));
var ry=degreesToRadians(ctrl.effect("Rotation Y")("Angle"));
var rz=degreesToRadians(ctrl.effect("Rotation Z")("Angle"));
try{if(ctrl.effect("Auto Rotate")("Checkbox")==1)
ry+=degreesToRadians(time*ctrl.effect("Rot Speed")("Slider"));}catch(e){}
var c1=Math.cos(rx),s1=Math.sin(rx);
var c2=Math.cos(ry),s2=Math.sin(ry);
var c3=Math.cos(rz),s3=Math.sin(rz);
function R(p){
var y1=p[1]*c1-p[2]*s1,z1=p[1]*s1+p[2]*c1,x1=p[0];
var x2=x1*c2+z1*s2,z2=-x1*s2+z1*c2,y2=y1;
var x3=x2*c3-y2*s3,y3=x2*s3+y2*c3;
var pr=ctrl.effect("Perspective")("Slider")/5000;
if(pr>0){var k=1/(1+z2*pr);x3*=k;y3*=k;}
return[x3,y3,z2];}
var vt=[[-W,-H,-D],[-W,-H,D],[-W,H,D],[-W,H,-D]];
var pts=[];
for(var i=0;i<vt.length;i++){var q=R(vt[i]);pts.push([q[0],q[1]]);}
createPath(pts,[],[],true);

var ctrl=thisComp.layer("3D Shape Ctrl");
var rx=degreesToRadians(ctrl.effect("Rotation X")("Angle"));
